nextflow_process {

    name "Test Process KAIJU_MERGEOUTPUTS"
    script "../main.nf"
    process "KAIJU_MERGEOUTPUTS"

    tag "modules"
    tag "modules_nfcore"
    tag "kaiju"
    tag "kaiju/kaiju"
    tag "kraken2/kraken2"
    tag "kaiju/mergeoutputs"

    test("sarscov2 - kraken2.kaiju.classified - noDB ") {
        def kraken2_db
        def kaiju_db
        setup {
            // params.modules_testdata_base_path is null outside the process string, so use the same env var and default as tests/config/nf-test.config
            def modules_testdata_base_path = System.getenv('NXF_MODULES_TESTDATA_BASE') ?: 'https://raw.githubusercontent.com/nf-core/test-datasets/modules/data/'
            kraken2_db = extract(modules_testdata_base_path + 'genomics/sarscov2/genome/db/kraken2.tar.gz').resolve('kraken2')
            kaiju_db = extract(modules_testdata_base_path + 'genomics/sarscov2/genome/db/kaiju.tar.gz').resolve('kaiju')
            run("KRAKEN2_KRAKEN2") {
                config "./nodb.config"
                script "../../../kraken2/kraken2/main.nf"
                process {
                    """
                    input[0] = [
                            [ id:'test', single_end:true ],
                            file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_1.fastq.gz', checkIfExists: true)
                            ]
                    input[1] = file('${kraken2_db}')
                    input[2] = false
                    input[3] = true
                    """
                }
            }
            run("KAIJU_KAIJU") {
                config "./nodb.config"
                script "../../../kaiju/kaiju/main.nf"
                process {
                    """
                    input[0] = [
                            [ id:'test', single_end:true ],
                            file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_1.fastq.gz', checkIfExists: true)
                            ]
                    input[1] = [
                        file('${kaiju_db}'),
                        file(params.modules_testdata_base_path + "delete_me/kaiju/nodes.dmp", checkIfExists: true),
                        file(params.modules_testdata_base_path + "delete_me/kaiju/names.dmp", checkIfExists: true)
                    ]
                    """
                }
            }
        }

        config "./nodb.config"

        when {
            process {
                """
                input[0] = KAIJU_KAIJU.out.results.join(KRAKEN2_KRAKEN2.out.classified_reads_assignment)
                input[1] = [ ]
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(process.out).match() }
            )
        }

    }

    test("sarscov2 - kraken2.kaiju.classified - kaiju.DB ") {
        def kraken2_db
        def kaiju_db
        setup {
            // params.modules_testdata_base_path is null outside the process string, so use the same env var and default as tests/config/nf-test.config
            def modules_testdata_base_path = System.getenv('NXF_MODULES_TESTDATA_BASE') ?: 'https://raw.githubusercontent.com/nf-core/test-datasets/modules/data/'
            kraken2_db = extract(modules_testdata_base_path + 'genomics/sarscov2/genome/db/kraken2.tar.gz').resolve('kraken2')
            kaiju_db = extract(modules_testdata_base_path + 'genomics/sarscov2/genome/db/kaiju.tar.gz').resolve('kaiju')
            run("KRAKEN2_KRAKEN2") {
                config "./nodb.config"
                script "../../../kraken2/kraken2/main.nf"
                process {
                    """
                    input[0] = [
                            [ id:'test', single_end:true ],
                            file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_1.fastq.gz', checkIfExists: true)
                            ]
                    input[1] = file('${kraken2_db}')
                    input[2] = false
                    input[3] = true
                    """
                }
            }
            run("KAIJU_KAIJU") {
                config "./nodb.config"
                script "../../../kaiju/kaiju/main.nf"
                process {
                    """
                    input[0] = [
                            [ id:'test', single_end:true ],
                            file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_1.fastq.gz', checkIfExists: true)
                            ]
                    input[1] = [
                        file('${kaiju_db}'),
                        file(params.modules_testdata_base_path + "delete_me/kaiju/nodes.dmp", checkIfExists: true),
                        file(params.modules_testdata_base_path + "delete_me/kaiju/names.dmp", checkIfExists: true)
                    ]
                    """
                }
            }
        }

        config "./db.config"
        when {
            process {
                """
                input[0] = KAIJU_KAIJU.out.results.join(KRAKEN2_KRAKEN2.out.classified_reads_assignment)
                input[1] = [
                    file('${kaiju_db}'),
                    file(params.modules_testdata_base_path + "delete_me/kaiju/nodes.dmp", checkIfExists: true),
                    file(params.modules_testdata_base_path + "delete_me/kaiju/names.dmp", checkIfExists: true)
                ]
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(process.out).match() }
            )
        }

    }

    test("sarscov2 - kraken2.kaiju.classified - noDB - stub ") {
        config "./nodb.config"
        options "-stub"

        when {
            process {
                """
                input[0] = [ [id: 'test', single_end: true], [], [] ]
                input[1] = []
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(process.out).match() }
            )
        }

    }

}

